// @pit: {"label": "Apply literal replacements across wait helpers and renderers"}
async ({ workspace: { read, edit } }, input: { files: Record<string, [string, string][]> }) => {
  const out: Record<string, string> = {};
  for (const [file, reps] of Object.entries(input.files)) {
    const r = await read(file, { format: "raw" });
    let text = r.content;
    for (const [before, after] of reps) {
      const n = text.split(before).length - 1;
      if (n !== 1) throw new Error(`${file}: expected 1 match, found ${n} for ${before.slice(0, 60)}`);
      text = text.replace(before, () => after);
    }
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: text }] });
    out[file] = "ok";
  }
  return out;
}

